INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 104411, 11, 1, 0, 0, "そろそろ野営の準備を始めねばな。\n食料は現地調達するしかないが、\n獣を狩るか、野草を採るか……", 1201320005, 10, 20132);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, 91, "", "", "", "", 1201320006, "", 20132);
