INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 101611, 11, 1, 0, 0, "ねねね！\nみんなで記念撮影しよ？\nあとで見返したら絶対エモいっしょ！", 1201620005, 10, 20162);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, 91, "", "", "", "", 1201620006, "", 20162);
